SELECT a.subject_id, a.gender, a.anchor_age, a.anchor_year, a.anchor_year_group, a.diagnosis_code, a.diagnosis_name, a.score, a.risk_category, a.risk_score, a.risk_percentile, b.score AS score_75_85, b.risk_category AS risk_category_75_85, b.risk_score AS risk_score_75_85, b.risk_percentile AS risk_percentile_75_85, c.score AS score_70_75, c.risk_category AS risk_category_70_75, c.risk_score AS risk_score_70_75, c.risk_percentile AS risk_percentile_70_75, d.score AS score_65_70, d.risk_category AS risk_category_65_70, d.risk_score AS risk_score_65_70, d.risk_percentile AS risk_percentile_65_70 FROM a JOIN b ON a.subject_id = b.subject_id JOIN c ON a.subject_id = c.subject_id JOIN d ON a.subject_id = d.subject_id WHERE a.score > 75 AND a.score < 85 AND b.score > 70 AND b.score < 75 AND c.score > 70 AND c.score < 75 AND d.score > 65 AND d.score < 70;